diff --git a/src/io/sales-import.js b/src/io/sales-import.js
new file mode 100644
index 0000000..2ab5846
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,61 @@
+import { isDate } from "../dates.js";
+import { memoryStore } from "../db/store.js";
+import { consume } from "../domain/batches.js";
+import { getDish } from "../domain/menu.js";
+import { getRecipe, scaled } from "../domain/recipes.js";
+import { AppError } from "../errors.js";
+import { parseCsv } from "./csv.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+const INSTANT = /^\d{4}-\d{2}-\d{2}T(?:[01]\d|2[0-3]):[0-5]\d(?::[0-5]\d(?:\.\d+)?)?(?:Z|[+-](?:[01]\d|2[0-3]):[0-5]\d)$/;
+
+/** Imports complete tickets atomically and returns ticket and portion counts. */
+export function importSales(store, text) {
+  const [header = [], ...rows] = parseCsv(text, { strict: true });
+  const columns = header.map((field) => field.trim());
+  if (columns.length !== HEADER.length || !HEADER.every((field) => columns.includes(field)))
+    throw new AppError("bad_request", { reason: "row 1: expected ticket,soldAt,dishId,qty columns" });
+
+  const staged = memoryStore(store.data);
+  const imported = new Set(staged.data.sales.map((sale) => sale.ticket));
+  const tickets = new Set();
+  let dishes = 0;
+  for (const [index, fields] of rows.entries()) {
+    const row = index + 2;
+    const invalid = (reason) => new AppError("bad_request", { reason: `row ${row}: ${reason}` });
+    if (fields.length !== columns.length) throw invalid("expected four fields");
+    const values = Object.fromEntries(columns.map((field, i) => [field, fields[i].trim()]));
+    const { ticket, soldAt } = values;
+    const dishId = Number(values.dishId);
+    const qty = Number(values.qty);
+    if (!ticket) throw invalid("ticket is required");
+    if (!INSTANT.test(soldAt) || !isDate(soldAt.slice(0, 10)) || !Number.isFinite(Date.parse(soldAt)))
+      throw invalid("soldAt must be an ISO instant");
+    if (!/^\d+$/.test(values.dishId) || !Number.isSafeInteger(dishId) || dishId < 1)
+      throw invalid("dishId must be a positive whole number");
+    if (!/^\d+$/.test(values.qty) || !Number.isSafeInteger(qty) || qty < 1 || !Number.isSafeInteger(dishes + qty))
+      throw invalid("qty must be a positive whole number");
+    if (imported.has(ticket)) continue;
+
+    const at = new Date(soldAt).toISOString();
+    let ingredients;
+    try {
+      ingredients = scaled(getRecipe(staged, getDish(staged, dishId).recipeId), qty);
+      for (const ingredient of ingredients) {
+        if (ingredient.qty > 0) consume(staged, ingredient.itemId, ingredient.qty, { at, ref: `sale:${ticket}` });
+      }
+    } catch (error) {
+      if (!(error instanceof AppError)) throw error;
+      if (error.code === "not_enough_stock")
+        throw new AppError(error.code, { ...error.params, prefix: `row ${row}: ` });
+      if (error.code === "not_found") throw invalid(`unknown dish or recipe for dish ${dishId}`);
+      if (error.code === "unknown_item") throw invalid(`unknown item ${error.params.id}`);
+      throw error;
+    }
+    staged.data.sales.push({ ticket, soldAt: at, dishId, qty, ingredients });
+    tickets.add(ticket);
+    dishes += qty;
+  }
+  store.data = staged.data;
+  return { tickets: tickets.size, dishes };
+}
